-- 15-line-matchups. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- Structured source line winners, unchanged.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_15;
CREATE TEMP TABLE afl_remaining_15_0 AS SELECT id, play_id, matchup_number, offense_player_id, defense_player_id, offense_team_id, defense_team_id, offense_slot, defense_slot, winner_side, detail_json FROM play_line_matchups WHERE 0;
CREATE TEMP TABLE afl_remaining_15_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_15_check BEFORE INSERT ON afl_remaining_15_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN (SELECT count(*) FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258'))<>9575 THEN RAISE(ROLLBACK,'Import all official plays (12) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_15_0 i JOIN play_line_matchups t ON t.id=i.id WHERE t.play_id IS NOT i.play_id OR t.matchup_number IS NOT i.matchup_number OR t.offense_player_id IS NOT i.offense_player_id OR t.defense_player_id IS NOT i.defense_player_id OR t.offense_team_id IS NOT i.offense_team_id OR t.defense_team_id IS NOT i.defense_team_id OR t.offense_slot IS NOT i.offense_slot OR t.defense_slot IS NOT i.defense_slot OR t.winner_side IS NOT i.winner_side OR t.detail_json IS NOT i.detail_json) THEN RAISE(ROLLBACK,'play_line_matchups: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_15_0 i JOIN play_line_matchups t ON t.play_id=i.play_id AND t.matchup_number=i.matchup_number WHERE NOT (t.id=i.id)) THEN RAISE(ROLLBACK,'play_line_matchups: natural key uses another ID.') END;
END;
DROP TRIGGER afl_remaining_15_check;
DROP TABLE afl_remaining_15_guard;
DROP TABLE afl_remaining_15_0;
RELEASE SAVEPOINT afl_remaining_15;
PRAGMA foreign_key_check;
SELECT 'play_line_matchups' AS imported_table,count(*) AS reviewed_records_present FROM play_line_matchups t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='60e4a3a3-466b-5f95-ae7d-b4181a1b054b' AND m.target_table='play_line_matchups' AND m.target_id=CAST(t.id AS TEXT));
